import type { jsPDF } from 'jspdf';

/**
 * Source Sans 3 (Adobe, licencia SIL Open Font License 1.1), recortada a los caracteres latinos y signos
 * que usan los informes. Se embebe en los PDF del plan y del informe final.
 */
export const PDF_FONTS: Record<string, string> = {
  regular: '',
  semibold: '',
  bold: '',
  italic: '',
  bolditalic: '',
};

/** Familias: "SS" (normal, bold, italic, bolditalic) y "SSsemi" (normal = seminegrita). */
export function registerPdfFonts(doc: jsPDF) {
  const add = (file: string, data: string, family: string, style: string) => { doc.addFileToVFS(file, data); doc.addFont(file, family, style); };
  add('SS-Regular.ttf', PDF_FONTS.regular, 'SS', 'normal');
  add('SS-Bold.ttf', PDF_FONTS.bold, 'SS', 'bold');
  add('SS-Italic.ttf', PDF_FONTS.italic, 'SS', 'italic');
  add('SS-BoldItalic.ttf', PDF_FONTS.bolditalic, 'SS', 'bolditalic');
  add('SS-SemiBold.ttf', PDF_FONTS.semibold, 'SSsemi', 'normal');
}
